    """Extend long horizontal colored runs to the right with color 1."""
    out = [row[:] for row in grid]
    if not grid:
        return out
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    width = len(grid[0])
    for r, row in enumerate(grid):
        c = 0
        while c < width:
            if row[c] == background:
                c += 1
                continue
            color = row[c]
            end = c + 1
            while end < width and row[end] == color:
                end += 1
            if end - c >= 5 and end < width:
                for j in range(end, width):
                    out[r][j] = 1
            c = end
    return out
